/**
 * Apple Health (HealthKit) Integration Service for VortexCal.
 *
 * Handles:
 * 1. Parsing Apple Health XML exports (`export.xml`).
 * 2. Parsing iOS Shortcut JSON payloads (1-tap sync via Apple Shortcuts).
 * 3. iOS Shortcut setup recipes and templates.
 */

export interface AppleHealthDayData {
  date: string; // YYYY-MM-DD
  steps?: number;
  activeEnergyKcal?: number;
  weightKg?: number;
  waterMl?: number;
  sleepHours?: number;
  bodyFatPct?: number;
  source: 'apple-health-xml' | 'apple-health-shortcut';
}

/**
 * Parses a JSON payload generated by an iOS Shortcut or copied from iPhone clipboard.
 * Supports single day or multi-day array payloads.
 */
export function parseAppleHealthShortcutJson(rawText: string): AppleHealthDayData[] {
  if (!rawText || !rawText.trim()) return [];

  try {
    let clean = rawText.trim();
    // Strip markdown code fences if user copied with ```json
    if (clean.startsWith('```')) {
      clean = clean.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    }

    const parsed = JSON.parse(clean);
    const list = Array.isArray(parsed) ? parsed : [parsed];

    const results: AppleHealthDayData[] = [];
    for (const item of list) {
      if (!item || typeof item !== 'object') continue;

      const date = item.date || item.Date || new Date().toISOString().slice(0, 10);
      const steps = Number(item.steps ?? item.stepCount ?? item.Steps);
      const activeEnergyKcal = Number(item.activeEnergyKcal ?? item.activeCalories ?? item.calories ?? item.Calories);
      const weightKg = Number(item.weightKg ?? item.weight ?? item.Weight);
      const waterMl = Number(item.waterMl ?? item.water ?? item.Water);
      const sleepHours = Number(item.sleepHours ?? item.sleep ?? item.Sleep);
      const bodyFatPct = Number(item.bodyFatPct ?? item.bodyFat ?? item.BodyFat);

      results.push({
        date: String(date).slice(0, 10),
        steps: Number.isFinite(steps) && steps > 0 ? Math.round(steps) : undefined,
        activeEnergyKcal: Number.isFinite(activeEnergyKcal) && activeEnergyKcal > 0 ? Math.round(activeEnergyKcal) : undefined,
        weightKg: Number.isFinite(weightKg) && weightKg > 0 ? Math.round(weightKg * 10) / 10 : undefined,
        waterMl: Number.isFinite(waterMl) && waterMl > 0 ? Math.round(waterMl) : undefined,
        sleepHours: Number.isFinite(sleepHours) && sleepHours > 0 ? Math.round(sleepHours * 10) / 10 : undefined,
        bodyFatPct: Number.isFinite(bodyFatPct) && bodyFatPct > 0 ? Math.round(bodyFatPct * 10) / 10 : undefined,
        source: 'apple-health-shortcut',
      });
    }

    return results;
  } catch {
    return [];
  }
}

/**
 * Parses Apple Health export XML content (or a snippet of export.xml).
 * Extracts steps, energy, weight, water, and sleep.
 */
export function parseAppleHealthXml(xmlString: string, targetDate?: string): AppleHealthDayData[] {
  if (!xmlString || !xmlString.trim()) return [];

  const dayMap: Record<string, Partial<AppleHealthDayData>> = {};

  const ensureDay = (d: string) => {
    if (!dayMap[d]) {
      dayMap[d] = {
        date: d,
        steps: 0,
        activeEnergyKcal: 0,
        waterMl: 0,
        sleepHours: 0,
        source: 'apple-health-xml',
      };
    }
    return dayMap[d];
  };

  // Regex parser matching <Record type="..." startDate="YYYY-MM-DD ..." value="..."/>
  const recordRegex = /<Record\s+[^>]*type="([^"]+)"[^>]*startDate="([^"\s]+)[^"]*"[^>]*value="([^"]+)"[^>]*\/>/g;
  let match: RegExpExecArray | null;

  while ((match = recordRegex.exec(xmlString)) !== null) {
    const type = match[1];
    const date = match[2];
    const val = parseFloat(match[3]);

    if (!date || isNaN(val)) continue;
    if (targetDate && date !== targetDate) continue;

    const entry = ensureDay(date);

    if (type.includes('StepCount')) {
      entry.steps = (entry.steps || 0) + val;
    } else if (type.includes('ActiveEnergyBurned')) {
      entry.activeEnergyKcal = (entry.activeEnergyKcal || 0) + val;
    } else if (type.includes('BodyMass')) {
      entry.weightKg = val; // Latest weight wins
    } else if (type.includes('DietaryWater')) {
      // Apple Health stores water in mL or L
      entry.waterMl = (entry.waterMl || 0) + (val < 10 ? val * 1000 : val);
    } else if (type.includes('BodyFatPercentage')) {
      entry.bodyFatPct = val < 1 ? Math.round(val * 1000) / 10 : Math.round(val * 10) / 10;
    }
  }

  // Sleep segments: <Record type="HKCategoryTypeIdentifierSleepAnalysis" startDate="..." endDate="..." .../>
  const sleepRegex = /<Record\s+[^>]*type="[^"]*SleepAnalysis"[^>]*startDate="([^"\s]+)\s+([^"]+)"[^>]*endDate="([^"\s]+)\s+([^"]+)"[^>]*\/>/g;
  while ((match = sleepRegex.exec(xmlString)) !== null) {
    const startDate = match[1];
    const startTime = match[2];
    const endDate = match[3];
    const endTime = match[4];

    if (targetDate && startDate !== targetDate && endDate !== targetDate) continue;

    const start = new Date(`${startDate}T${startTime}`).getTime();
    const end = new Date(`${endDate}T${endTime}`).getTime();
    if (!isNaN(start) && !isNaN(end) && end > start) {
      const hours = (end - start) / 3600000;
      const entry = ensureDay(endDate || startDate);
      entry.sleepHours = (entry.sleepHours || 0) + hours;
    }
  }

  return Object.values(dayMap).map((d) => ({
    date: d.date!,
    steps: d.steps ? Math.round(d.steps) : undefined,
    activeEnergyKcal: d.activeEnergyKcal ? Math.round(d.activeEnergyKcal) : undefined,
    weightKg: d.weightKg ? Math.round(d.weightKg * 10) / 10 : undefined,
    waterMl: d.waterMl ? Math.round(d.waterMl) : undefined,
    sleepHours: d.sleepHours ? Math.round(d.sleepHours * 10) / 10 : undefined,
    bodyFatPct: d.bodyFatPct,
    source: 'apple-health-xml',
  }));
}

/**
 * iOS Shortcuts recipe: prompt text that instructs the user or iOS Shortcuts app
 * how to fetch Apple Health data with 1 tap.
 */
export const IOS_SHORTCUT_RECIPE = `
📱 HƯỚNG DẪN TẠO PHÍM TẮT ĐỒNG BỘ APPLE HEALTH (1 CHẠM TRÊN IPHONE):

1. Mở ứng dụng "Phím tắt" (Shortcuts) trên iPhone.
2. Bấm dấu (+) để tạo phím tắt mới, đặt tên: "Đồng Bộ VortexCal".
3. Thêm các tác vụ sau:
   - "Tìm mẫu sức khỏe": Lấy Số bước hôm nay (Step Count)
   - "Tìm mẫu sức khỏe": Lấy Năng lượng tiêu hao hôm nay (Active Energy)
   - "Tìm mẫu sức khỏe": Lấy Cân nặng gần nhất (Body Mass)
   - "Tìm mẫu sức khỏe": Lấy Giấc ngủ đêm qua (Sleep Analysis)
   - "Tìm mẫu sức khỏe": Lấy Lượng nước uống hôm nay (Water)
4. Thêm tác vụ "Văn bản" (Text) với nội dung JSON:
{
  "date": "Current Date (định dạng YYYY-MM-DD)",
  "steps": (Số bước),
  "activeEnergyKcal": (Năng lượng tiêu hao),
  "weightKg": (Cân nặng),
  "sleepHours": (Giấc ngủ tính theo giờ),
  "waterMl": (Lượng nước)
}
5. Thêm tác vụ "Sao chép vào Bộ nhớ tạm" (Copy to Clipboard) hoặc "Mở URL" với trang web VortexCal.
`;

